@page "/board"
@rendermode InteractiveServer
@inject ITaskService TaskService

<PageTitle>Kanban Board</PageTitle>

<h1>Project Board</h1>

@if (_loading)
{
    <p><em>Loading tasks...</em></p>
}
else if (_error is not null)
{
    <div class="alert alert-danger">@_error</div>
}
else
{
    <!-- Summary Stats Bar -->
    <div class="row mb-3">
        <div class="col">
            <div class="d-flex gap-3 flex-wrap align-items-center bg-light p-2 rounded">
                <span><strong>Total:</strong> @FilteredTasks.Count</span>
                <span><strong>To Do:</strong> @TodoTasks.Count</span>
                <span><strong>In Progress:</strong> @InProgressTasks.Count</span>
                <span><strong>Done:</strong> @DoneTasks.Count</span>
                <span class="text-danger"><strong>Overdue:</strong> @OverdueCount</span>
            </div>
        </div>
    </div>

    <!-- Search Bar -->
    <div class="row mb-3">
        <div class="col-md-4">
            <input type="text" class="form-control" placeholder="Search tasks by title..."
                   @bind="_searchQuery" @bind:event="oninput" />
        </div>
    </div>

    <!-- Kanban Columns -->
    <div class="row">
        @RenderColumn("To Do", TodoTasks, null, "In Progress")
        @RenderColumn("In Progress", InProgressTasks, "To Do", "Done")
        @RenderColumn("Done", DoneTasks, "In Progress", null)
    </div>
}

@code {
    private List<TaskItem> _tasks = new();
    private bool _loading = true;
    private string? _error;
    private string _searchQuery = string.Empty;

    private Dictionary<string, bool> _showAddForm = new()
    {
        ["To Do"] = false,
        ["In Progress"] = false,
        ["Done"] = false
    };

    private Dictionary<string, AddTaskModel> _addModels = new()
    {
        ["To Do"] = new(),
        ["In Progress"] = new(),
        ["Done"] = new()
    };

    private List<TaskItem> FilteredTasks => string.IsNullOrWhiteSpace(_searchQuery)
        ? _tasks
        : _tasks.Where(t => t.Title.Contains(_searchQuery, StringComparison.OrdinalIgnoreCase)).ToList();

    private List<TaskItem> TodoTasks => FilteredTasks.Where(t => t.Status == "To Do").ToList();
    private List<TaskItem> InProgressTasks => FilteredTasks.Where(t => t.Status == "In Progress").ToList();
    private List<TaskItem> DoneTasks => FilteredTasks.Where(t => t.Status == "Done").ToList();

    private int OverdueCount => FilteredTasks.Count(t => t.DueDate < DateTime.Today);

    protected override async Task OnInitializedAsync()
    {
        try
        {
            _tasks = await TaskService.GetAllTasksAsync();
        }
        catch (Exception ex)
        {
            _error = $"Failed to load tasks: {ex.Message}";
        }
        finally
        {
            _loading = false;
        }
    }

    private RenderFragment RenderColumn(string status, List<TaskItem> tasks, string? leftStatus, string? rightStatus) => __builder =>
    {
        <div class="col-md-4">
            <div class="card">
                <div class="card-header d-flex justify-content-between align-items-center">
                    <strong>@status</strong>
                    <span class="badge bg-secondary">@tasks.Count</span>
                </div>
                <div class="card-body">
                    @foreach (var task in tasks)
                    {
                        <div class="card mb-2">
                            <div class="card-body p-2">
                                <h6 class="card-title mb-1">@task.Title</h6>
                                <p class="card-text mb-1 small text-muted">@task.Assignee</p>
                                <div class="d-flex justify-content-between align-items-center mb-1">
                                    <span class="badge @GetPriorityClass(task.Priority)">@task.Priority</span>
                                    <small class="text-muted">@task.DueDate.ToString("MMM dd")</small>
                                </div>
                                <div class="d-flex gap-1">
                                    @if (leftStatus is not null)
                                    {
                                        <button class="btn btn-sm btn-outline-secondary"
                                                @onclick="() => MoveTask(task.Id, leftStatus)">← Move Left</button>
                                    }
                                    @if (rightStatus is not null)
                                    {
                                        <button class="btn btn-sm btn-outline-secondary"
                                                @onclick="() => MoveTask(task.Id, rightStatus)">Move Right →</button>
                                    }
                                </div>
                            </div>
                        </div>
                    }

                    @if (_showAddForm[status])
                    {
                        var model = _addModels[status];
                        <div class="card mt-2 border-primary">
                            <div class="card-body p-2">
                                <input type="text" class="form-control form-control-sm mb-1"
                                       placeholder="Title" @bind="model.Title" />
                                <input type="text" class="form-control form-control-sm mb-1"
                                       placeholder="Assignee" @bind="model.Assignee" />
                                <select class="form-select form-select-sm mb-1" @bind="model.Priority">
                                    <option value="High">High</option>
                                    <option value="Medium">Medium</option>
                                    <option value="Low">Low</option>
                                </select>
                                <input type="date" class="form-control form-control-sm mb-1"
                                       @bind="model.DueDate" />
                                <div class="d-flex gap-1">
                                    <button class="btn btn-sm btn-primary"
                                            @onclick="() => SaveTask(status)">Save</button>
                                    <button class="btn btn-sm btn-secondary"
                                            @onclick="() => CancelAdd(status)">Cancel</button>
                                </div>
                            </div>
                        </div>
                    }
                    else
                    {
                        <button class="btn btn-sm btn-outline-primary mt-2 w-100"
                                @onclick="() => ShowAddForm(status)">+ Add Task</button>
                    }
                </div>
            </div>
        </div>
    };

    private string GetPriorityClass(string priority) => priority switch
    {
        "High" => "bg-danger",
        "Medium" => "bg-warning text-dark",
        "Low" => "bg-success",
        _ => "bg-secondary"
    };

    private async Task MoveTask(int taskId, string newStatus)
    {
        try
        {
            await TaskService.UpdateTaskStatusAsync(taskId, newStatus);
            var task = _tasks.First(t => t.Id == taskId);
            var index = _tasks.IndexOf(task);
            _tasks[index] = task with { Status = newStatus };
        }
        catch (Exception ex)
        {
            _error = $"Failed to move task: {ex.Message}";
        }
    }

    private void ShowAddForm(string status)
    {
        _showAddForm[status] = true;
        _addModels[status] = new();
    }

    private void CancelAdd(string status)
    {
        _showAddForm[status] = false;
    }

    private async Task SaveTask(string status)
    {
        var model = _addModels[status];
        if (string.IsNullOrWhiteSpace(model.Title))
            return;

        try
        {
            var newTask = await TaskService.CreateTaskAsync(model.Title, model.Assignee, model.Priority, model.DueDate);
            _tasks.Add(newTask with { Status = status });
            _showAddForm[status] = false;
        }
        catch (Exception ex)
        {
            _error = $"Failed to create task: {ex.Message}";
        }
    }

    private class AddTaskModel
    {
        public string Title { get; set; } = string.Empty;
        public string Assignee { get; set; } = string.Empty;
        public string Priority { get; set; } = "Medium";
        public DateTime DueDate { get; set; } = DateTime.Today.AddDays(7);
    }
}

